        // Shift again -> 4'b0001
        check_q(4'b0001);

        // Shift again -> 4'b0000
        check_q(4'b0000);

        // Test 5: Priority Test (load and ena both asserted)
        // Load should take precedence over enable
        @(negedge clk);
        load = 1;
        ena = 1;
        data = 4'b1100;
        check_q(4'b1100);

        // Test 6: Asynchronous reset during operation
        @(negedge clk);
        load = 0;
        ena = 1;
        #2;
        areset = 1; // Mid-cycle async reset
